(select f.rival_account_no from hls_itfc_bank_flow f where f.flow_id=tt1.flow_no and rownum = 1) rival_account_no, (select f.rival_account_no from hls_itfc_bank_flow f where f.flow_id=tt1.flow_no and rownum=1) flow_no_n, (select f.rival_account_name from hls_itfc_bank_flow f where f.flow_id=tt1.flow_no and rownum = 1) rival_account_name, tt1.actual_payment_amount, tt1.payment_amount, tt2.bp_bank_account_id csh_bank_account_id, tt2.bp_bank_account_name csh_bank_account_name, tt2.bp_bank_account_num csh_bank_account_num, tt1.csh_bank_id FROM csh_pay_req_ln_bank_account tt1, csh_payment_req_ln t, csh_payment_req_hd tt2
