SELECT tt1.payment_amount, tt1.rate, tt1.actual_payment_amount, tt1.csh_bank_account_id, tt1.csh_bank_account_num, tt1.csh_bank_account_name, tt1.created_by, tt1.creation_date, tt1.last_updated_by, tt1.last_update_date, tt1.last_update_login, tt1.object_version_number, tt1.request_id, tt1.program_id, tt1.csh_bank_id, tt1.payment_name_id, tt1.payment_name, tt1.actual_payment_date, tt1.process_instance_id, tt1.flow_no, tt1.trade_no, tt1.purpose, tt1.apy_number, tt1.csh_bank_branch_name, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'CSH.PAYMENT_METHOD' and scvb.value = t.payment_method) payment_name_n, t.FUNDING_PLAN_LN_ID,
