SELECT * FROM ( SELECT cc.contract_number AS payment_number, cc.contract_name, pp.contract_number, (select hb.bp_name from hls_bp_master hb where hb.bp_id=hd.bp_id) bp_name, pp.contract_amount, fc.currency_name AS currency_n, ( SELECT abs.currency_name FROM fnd_currency abs WHERE abs.CURRENCY_CODE = hd.CURRENCY ) AS currency_fk_n, hd.proposed_launch_date, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = hd.PAYMENT_TYPE ) PAYMENT_TYPE_N, hd.loan_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = hd.loan_type ) LOAN_TYPE_N, ( SELECT scvb.meaning FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.code_id = scb.code_id AND scb. CODE = 'CSH.PAYMENT_METHOD' AND scvb. VALUE = ln.PAYMENT_METHOD ) PAYMENT_METHOD_n, ln.PAYMENT_METHOD, hbr.BILL_APPLY_NUMBER bill_id_n, hbm.bp_name bp_id_n, ln.BP_BANK_ACCOUNT_NAME bp_bank_account_name_n, ln.BP_BANK_ACCOUNT_NAME, ln.bp_bank_account_num, ln.bp_bank_branch_name, lnba.payment_name, lnba.CSH_BANK_ACCOUNT_ID, lnba.CSH_BANK_ACCOUNT_NAME AS CSH_BANK_ACCOUNT_ID_N, lnba.csh_bank_account_num, lnba.actual_payment_date, lnba.payment_amount, lnba.rate, lnba.actual_payment_amount FROM csh_pay_req_ln_bank_account lnba, csh_payment_req_ln ln LEFT JOIN hls_bill_request hbr ON hbr.bill_id = ln.bill_id LEFT JOIN hls_bp_master hbm ON hbm.bp_id = ln.bp_id, csh_payment_req_hd hd LEFT JOIN con_contract cc ON cc.CONTRACT_ID = hd.SOURCE_CONTRACT_ID LEFT JOIN prj_project pp ON cc.project_id = pp.project_id LEFT JOIN fnd_currency fc ON fc.currency_code = hd.contract_currency_id WHERE lnba.PAYMENT_REQ_LN_ID = ln.PAYMENT_REQ_LN_ID AND ln.PAYMENT_REQ_ID = hd.PAYMENT_REQ_ID ) t
